import { useMutation, useMutationState, useQuery, useQueryClient } from '@tanstack/react-query'
import type { UseMutationResult, UseQueryResult } from '@tanstack/react-query'

import { client, unwrap } from '@/api/client'
import type { components } from '@/api/schema'

import type { TodoTask } from '../lib/todoTask'

export type TodoTaskList = components['schemas']['TodoTaskList']
export type TodoTaskCreate = components['schemas']['TodoTaskCreate']
type TodoTaskUpdate = components['schemas']['TodoTaskUpdate']

/**
 * A tick: the task, and the state the person chose for it -- the one field of
 * `TodoTaskUpdate` a tick sends, required here because a tick always carries it.
 */
export interface TodoTaskMarking {
  id: TodoTask['id']
  done: NonNullable<TodoTaskUpdate['done']>
}

/** A correction: the task, and its new text as the shared rule leaves it -- `text` alone. */
export interface TodoTaskCorrection {
  id: TodoTask['id']
  text: NonNullable<TodoTaskUpdate['text']>
}

/**
 * The one place the screen's copy of the to-do list is read and written.
 *
 * Two promises live here and nowhere else (`spec/design/architecture.md` § The
 * to-do list -- where each rule lives; `spec/design/ui/todo-list.md` § Data):
 *
 * 1. **The cache is written only from the application's answer.** No mutation
 *    below has an `onMutate`, and none writes an answer into the cached list by
 *    hand -- so no row, tick or text is ever on screen before the service has
 *    stored it, and nothing is left there after a failure (`R-10`). An optimistic
 *    tick rolled back on failure is still a tick the person saw made, on the one
 *    list whose whole point is saying what is done.
 * 2. **A change that went through is followed by a fresh read of the whole list**,
 *    which is also when other people's changes arrive (`R-1`). The answer to a
 *    write is one task; the list around it may have moved meanwhile, and only a
 *    read can say how.
 *
 * The fresh read is awaited inside each mutation's own `onSuccess`, so a write is
 * still pending until the list it changed has been read again. That is what lets
 * the screen say "Task added." and show the task in the same moment, and what
 * lets a deleted row leave the list at the moment its question closes, rather than
 * a beat later with the row briefly back as if nothing had happened.
 *
 * Components never call the client themselves (`spec/design/conventions.md`
 * § Frontend); this module is the only place the key shape exists.
 */
export const todoTaskKeys = {
  all: ['todo-tasks'] as const,
  list: () => ['todo-tasks', 'list'] as const,
  /** Every tick in flight carries this key, so the screen can tell which boxes are locked. */
  marking: () => ['todo-tasks', 'marking'] as const,
}

/**
 * The whole list, as the service orders it.
 *
 * No parameters and no pages: the list is read whole and shown in the order it
 * arrives, never sorted again (`BR-11`, `spec/design/api.md` § The to-do list's
 * endpoints).
 */
export function useTodoTasks(): UseQueryResult<TodoTaskList> {
  return useQuery({
    queryKey: todoTaskKeys.list(),
    queryFn: () => unwrap(client.GET('/api/todo-tasks')),
  })
}

/** Add a task -- the text as the shared rule leaves it -- then read the list again. */
export function useAddTodoTask(): UseMutationResult<TodoTask, Error, TodoTaskCreate> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (body: TodoTaskCreate) => unwrap(client.POST('/api/todo-tasks', { body })),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: todoTaskKeys.all }),
  })
}

/**
 * Mark a task done or not done, then read the list again.
 *
 * **It sends `done` alone, carrying the state chosen** -- never "the opposite of
 * what is stored", and never the text written back: two people ticking the same
 * task done both end with it done, and a tick and a correction sent at the same
 * moment are both kept (`BR-09`, `BR-10`, `spec/design/api.md` § `TodoTaskUpdate`).
 *
 * Every tick carries `todoTaskKeys.marking()`, because several can travel at once
 * -- one per row -- and a mutation observer only remembers the last one it sent.
 * `useTodoTasksBeingMarked` reads them all.
 */
export function useMarkTodoTask(): UseMutationResult<TodoTask, Error, TodoTaskMarking> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationKey: todoTaskKeys.marking(),
    mutationFn: ({ id, done }: TodoTaskMarking) =>
      unwrap(
        client.PATCH('/api/todo-tasks/{todo_task_id}', {
          params: { path: { todo_task_id: id } },
          body: { done },
        }),
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: todoTaskKeys.all }),
  })
}

/**
 * The tasks whose tick is travelling right now -- each one's box is locked on the
 * state that is stored until its own answer comes (`spec/design/ui/todo-list.md`
 * § A task's row, `loading`).
 */
export function useTodoTasksBeingMarked(): string[] {
  return useMutationState({
    filters: { mutationKey: todoTaskKeys.marking(), status: 'pending' },
    select: (mutation) => (mutation.state.variables as TodoTaskMarking).id,
  })
}

/**
 * Correct a task's text, then read the list again.
 *
 * **It sends `text` alone**, so the done mark somebody else may be changing at the
 * same moment is never written back (`BR-10`).
 */
export function useCorrectTodoTask(): UseMutationResult<TodoTask, Error, TodoTaskCorrection> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, text }: TodoTaskCorrection) =>
      unwrap(
        client.PATCH('/api/todo-tasks/{todo_task_id}', {
          params: { path: { todo_task_id: id } },
          body: { text },
        }),
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: todoTaskKeys.all }),
  })
}

/**
 * Delete a task for good, then read the list again. The answer is a `204` with
 * no body, and it is the success, not a body (`BR-13`).
 */
export function useDeleteTodoTask(): UseMutationResult<void, Error, string> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: async (id: string) => {
      await unwrap(
        client.DELETE('/api/todo-tasks/{todo_task_id}', {
          params: { path: { todo_task_id: id } },
        }),
      )
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: todoTaskKeys.all }),
  })
}

import { useEffect, useRef, useState } from 'react'

import { problemOf } from '@/api/problem'
import { PageFrame } from '@/components/shell/PageFrame'
import { ErrorState, Skeleton } from '@/components/ui/Feedback'
import { useToast } from '@/components/ui/Toast'

import { TodoTaskComposer } from '../components/TodoTaskComposer'
import { TodoTaskRow } from '../components/TodoTaskRow'
import {
  useAddTodoTask,
  useCorrectTodoTask,
  useDeleteTodoTask,
  useMarkTodoTask,
  useTodoTasks,
  useTodoTasksBeingMarked,
} from '../hooks/useTodoTasks'
import { TODO_TASK_DONE_NOTICES, todoTaskCountLabel, todoTaskFailure } from '../lib/todoTask'
import type { RefusedText, TodoTask } from '../lib/todoTask'

/**
 * `S-02` -- the one shared to-do list (`spec/design/ui/todo-list.md`,
 * `spec/contexts/todo_list.md` § `P-02`).
 *
 * One column: the add field at the top, the list right under it, newest first,
 * done and not done alike, with nothing to press to see more. Anybody who opens it
 * adds, ticks, corrects and deletes, with no sign-in, because there is no identity
 * here.
 *
 * **Four list states, and the two easy to confuse are told apart.** Loading is
 * rows in outline and no count; empty is a sentence saying how to begin, with no
 * error and `0 tasks`; failed is its own sentence above the shared error card, with
 * no count and never the empty sentence -- a list that could not be read is not a
 * list with nothing in it; and a list whose every task is done is simply the list
 * (`R-3`, `R-10`).
 *
 * **A change is shown as made only once the answer says it was stored**, and the
 * list is read again after every change that went through (`useTodoTasks.ts`).
 * Every failure is told where the write started, in the words the person agreed
 * (§ Copy, `Q-15`): a refusal of a text under its field, everything else in an
 * error notice over a screen that still shows what is stored -- the text typed
 * stays in its field, the box as it was, the row still there.
 *
 * The add field stays usable while the list loads or has failed: adding does not
 * depend on having read the list.
 */
export function TodoListPage() {
  const list = useTodoTasks()
  const add = useAddTodoTask()
  const mark = useMarkTodoTask()
  const correct = useCorrectTodoTask()
  const remove = useDeleteTodoTask()
  const beingMarked = useTodoTasksBeingMarked()
  const toast = useToast()

  /** The row whose editor is open -- at most one, anywhere on the list. */
  const [editingId, setEditingId] = useState<string | undefined>(undefined)
  /** How many tasks the field has added; it empties itself when this grows. */
  const [added, setAdded] = useState(0)
  /** The task the last add stored, which arrives with the frame's entry animation. */
  const [arrivedId, setArrivedId] = useState<string | undefined>(undefined)
  /** Bumped after each deletion that went through, to look after the focus it leaves. */
  const [deletions, setDeletions] = useState(0)

  const listRef = useRef<HTMLUListElement>(null)
  const emptyRef = useRef<HTMLDivElement>(null)

  /**
   * A deleted row takes its question with it, and the focus that was in the
   * question has nowhere to go back to. It goes to the list -- or to the empty
   * sentence, when that was the last task -- and never to the page's start
   * (§ Keyboard and accessibility). After the commit, because the row leaves in a
   * render of its own.
   */
  useEffect(() => {
    if (deletions === 0) return
    const active = document.activeElement
    if (active === null || active === document.body) (listRef.current ?? emptyRef.current)?.focus()
  }, [deletions])

  function tellFailure(error: unknown, write: 'add' | 'change') {
    const failure = todoTaskFailure(problemOf(error), write)
    // A refusal of the text is told under the field that holds it (below), not
    // in a notice as well.
    if (failure.place === 'notice') toast.push(failure.sentence, 'error')
  }

  function handleAdd(values: { text: string }) {
    add.mutate(values, {
      onSuccess: (task) => {
        setAdded((count) => count + 1)
        setArrivedId(task.id)
        toast.push(TODO_TASK_DONE_NOTICES.added, 'success')
      },
      onError: (error) => tellFailure(error, 'add'),
    })
  }

  function handleMark(task: TodoTask, done: boolean) {
    // Per call rather than through `mutate`'s own callbacks: several ticks can
    // travel at once, and those callbacks fire for the last one sent alone. A
    // tick that went through gets no notice -- the box is its own confirmation.
    mark.mutateAsync({ id: task.id, done }).catch((error: unknown) => tellFailure(error, 'change'))
  }

  function handleSave(task: TodoTask, values: { text: string }) {
    correct.mutate(
      { id: task.id, text: values.text },
      {
        onSuccess: () => {
          // Only the editor that sent it: "Edit" is locked everywhere while a
          // correction travels, so it is still this one -- said here anyway,
          // because an answer must never close an editor it did not open.
          setEditingId((current) => (current === task.id ? undefined : current))
          toast.push(TODO_TASK_DONE_NOTICES.corrected, 'success')
        },
        // The editor stays open with what was typed, to be sent again or cancelled.
        onError: (error) => tellFailure(error, 'change'),
      },
    )
  }

  /** Settles once the deletion has been answered -- the row closes its question on it. */
  function handleDelete(task: TodoTask): Promise<void> {
    return remove.mutateAsync(task.id).then(
      () => {
        // A deletion of the row being edited closes its editor with it.
        setEditingId((current) => (current === task.id ? undefined : current))
        setDeletions((count) => count + 1)
        toast.push(TODO_TASK_DONE_NOTICES.deleted, 'success')
      },
      (error: unknown) => tellFailure(error, 'change'),
    )
  }

  const addRefusal = refusedText(add.isError ? add.error : undefined, add.variables?.text, 'add')
  const correctionRefusal = refusedText(
    correct.isError ? correct.error : undefined,
    correct.variables?.text,
    'change',
  )

  return (
    <PageFrame
      title="Things to do"
      lede="No account, no sign-in, one list for everybody. Add what needs doing and tick it off when it is done. Anyone can edit or delete any task."
      meta={list.isSuccess ? todoTaskCountLabel(list.data.total) : undefined}
      footer="Tasks are public and editable by anyone with this link."
    >
      <TodoTaskComposer
        onSubmit={handleAdd}
        isPending={add.isPending}
        addedCount={added}
        refusal={addRefusal}
      />

      {list.isPending && <TodoTaskSkeletons />}

      {list.isError && (
        <>
          <p className="m-0 mb-4 text-meta text-muted">The tasks could not be loaded.</p>
          <ErrorState problem={problemOf(list.error)} onRetry={() => void list.refetch()} />
        </>
      )}

      {list.isSuccess && list.data.items.length === 0 && (
        <div
          ref={emptyRef}
          tabIndex={-1}
          className="rounded-card border border-dashed border-line px-5 py-14 text-center text-body text-muted"
        >
          No tasks yet. Add the first one above.
        </div>
      )}

      {list.isSuccess && list.data.items.length > 0 && (
        // In the order the tasks arrive, sorted by nothing here (`BR-11`): the
        // service settles ties and directions, and a screen that sorted again
        // could only disagree with it. A tick and a correction never move a row.
        <ul
          ref={listRef}
          aria-label="Tasks"
          tabIndex={-1}
          className="m-0 list-none divide-y divide-hairline overflow-hidden rounded-card border border-hairline bg-card p-0"
        >
          {list.data.items.map((task) => (
            <TodoTaskRow
              key={task.id}
              task={task}
              isEditing={editingId === task.id}
              onEditStart={() => setEditingId(task.id)}
              onEditCancel={() => setEditingId(undefined)}
              onSave={(values) => handleSave(task, values)}
              onMark={({ done }) => handleMark(task, done)}
              onDelete={() => handleDelete(task)}
              isMarking={beingMarked.includes(task.id)}
              isSaving={correct.isPending && correct.variables?.id === task.id}
              isSaveInFlight={correct.isPending}
              isDeleting={remove.isPending && remove.variables === task.id}
              saveRefusal={correct.variables?.id === task.id ? correctionRefusal : undefined}
              isArriving={task.id === arrivedId}
            />
          ))}
        </ul>
      )}
    </PageFrame>
  )
}

/**
 * The text a write sent and the service refused, with the service's sentence --
 * or nothing, when the write did not fail on its text.
 */
function refusedText(
  error: Error | undefined,
  text: string | undefined,
  write: 'add' | 'change',
): RefusedText | undefined {
  if (error === undefined || text === undefined) return undefined
  const failure = todoTaskFailure(problemOf(error), write)
  return failure.place === 'field' ? { text, sentence: failure.sentence } : undefined
}

/**
 * Four rows in outline inside the list's card while the list is read.
 *
 * The height is reserved and nothing spins: the content does not jump under the
 * cursor when it arrives, and a spinner over an empty column could not be told
 * from a list with nothing in it -- the one thing this screen has to say clearly.
 */
function TodoTaskSkeletons() {
  const widths = ['w-2/5', 'w-3/5', 'w-1/2', 'w-4/5']
  return (
    <div
      role="status"
      aria-label="Loading tasks"
      className="divide-y divide-hairline overflow-hidden rounded-card border border-hairline bg-card"
    >
      {widths.map((width) => (
        <div key={width} className="flex items-center gap-4 px-5 py-4">
          <Skeleton className="size-5 shrink-0" />
          <Skeleton className={`h-2.5 ${width}`} />
        </div>
      ))}
    </div>
  )
}

import { useEffect, useId, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'

import { normalizeText } from '@/lib/text'

import { TODO_TASK_TEXT_REFUSALS, todoTaskTextVerdict } from '../lib/todoTask'
import type { RefusedText } from '../lib/todoTask'

/**
 * The add field: one line and "Add task", in a white card
 * (`spec/design/ui/todo-list.md` § The add field).
 *
 * **Nothing stops input at a length.** No `maxLength`, no counter, no cut: a
 * `maxLength` counts UTF-16 code units, so on a text of emoji it stops at half the
 * bound -- the guestbook's defect (`D-04`), one context over. The field holds
 * whatever is typed or pasted, and the rule decides, in the unit the service
 * counts in; the sentence under the field is the bound.
 *
 * **The rule is the service's, applied before sending** (`BR-06`, `BR-07`), from
 * `lib/todoTask.ts`, and what is sent is the text as the shared rule leaves it --
 * normalized and trimmed -- so the screen judged the very string the service will
 * store. The sentence for the one reason a text is refused appears once the field
 * has been left or Enter pressed, never while typing, and goes as soon as the text
 * passes. Until then "Add task" is simply closed, and the empty field's placeholder
 * says what it is waiting for.
 *
 * **Enter is handled on the key, not by a form's implicit submission**, because a
 * form does not submit through a closed button -- and Enter on a refused text has
 * to say why rather than do nothing.
 *
 * The field carries no visible label, matching the mock-up; it is named "New task"
 * for everything that is not looking at the page.
 */
export interface TodoTaskComposerProps {
  /** An accepted text, as the shared rule leaves it. */
  onSubmit: (values: { text: string }) => void
  /** True while an add travels: the field and the button lock, the text stays. */
  isPending?: boolean
  /**
   * How many tasks this field has added. When it grows, the add went through and
   * the field empties itself for the next one; a failed add leaves the text where
   * it was, because retrying otherwise means typing it again.
   */
  addedCount?: number
  /** The service refused the text it was sent: its sentence stands under the field while it holds that text. */
  refusal?: RefusedText
}

export function TodoTaskComposer({
  onSubmit,
  isPending = false,
  addedCount = 0,
  refusal,
}: TodoTaskComposerProps) {
  const errorId = useId()
  const cardRef = useRef<HTMLDivElement>(null)
  const fieldRef = useRef<HTMLInputElement>(null)
  const [text, setText] = useState('')
  const [shown, setShown] = useState(false)

  // Emptied during the render in which the count grows, so the field is never
  // drawn for a frame still holding the task that was just added.
  const [seenAdded, setSeenAdded] = useState(addedCount)
  if (addedCount !== seenAdded) {
    setSeenAdded(addedCount)
    setText('')
    setShown(false)
  }

  const verdict = todoTaskTextVerdict(text)
  const sent = normalizeText(text)
  const sentence =
    shown && verdict !== 'accepted'
      ? TODO_TASK_TEXT_REFUSALS[verdict]
      : refusal !== undefined && refusal.text === sent
        ? refusal.sentence
        : undefined
  const canAdd = verdict === 'accepted' && !isPending

  /**
   * After any add, whether it went through or not, the focus goes back in the
   * field (`Q-16`) -- so the next task can be typed at once, or the text that
   * stayed sent again. Only when the add was sent from this card and the focus has
   * not been put somewhere else since: the field and the button lock while the add
   * travels, and a locked control lets go of the focus.
   */
  const hadFocus = useRef(false)
  const wasPending = useRef(isPending)
  useEffect(() => {
    if (wasPending.current && !isPending && hadFocus.current) {
      const active = document.activeElement
      const free =
        active === null ||
        active === document.body ||
        (cardRef.current?.contains(active) ?? false)
      if (free) fieldRef.current?.focus()
      hadFocus.current = false
    }
    wasPending.current = isPending
  }, [isPending])

  function submit() {
    if (isPending) return
    if (verdict !== 'accepted') {
      setShown(true)
      return
    }
    hadFocus.current = cardRef.current?.contains(document.activeElement) ?? false
    onSubmit({ text: sent })
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter' || event.nativeEvent.isComposing) return
    event.preventDefault()
    submit()
  }

  return (
    <section className="pt-7 pb-5">
      <div
        ref={cardRef}
        className="flex flex-col gap-2 rounded-card border border-hairline bg-card py-3 pr-3 pl-4.5"
      >
        <div className="flex items-center gap-3">
          <input
            ref={fieldRef}
            type="text"
            aria-label="New task"
            placeholder="What needs doing?"
            autoComplete="off"
            value={text}
            disabled={isPending}
            aria-invalid={sentence !== undefined}
            aria-describedby={sentence !== undefined ? errorId : undefined}
            onChange={(event) => {
              const next = event.target.value
              setText(next)
              if (todoTaskTextVerdict(next) === 'accepted') setShown(false)
            }}
            onBlur={() => setShown(verdict !== 'accepted')}
            onKeyDown={handleKeyDown}
            className="min-w-0 flex-1 border-0 bg-transparent p-0 text-base leading-6 text-ink disabled:cursor-progress disabled:text-muted"
          />
          <button
            type="button"
            onClick={submit}
            disabled={!canAdd}
            className="shrink-0 cursor-pointer rounded-control border-0 bg-accent px-5 py-2.5 text-sm font-medium text-inverse enabled:hover:brightness-112 disabled:cursor-not-allowed disabled:opacity-35"
          >
            {isPending ? 'Adding…' : 'Add task'}
          </button>
        </div>
        {sentence !== undefined && (
          <span id={errorId} role="alert" className="text-xs font-medium text-danger">
            {sentence}
          </span>
        )}
      </div>
    </section>
  )
}

import { useEffect, useId, useRef, useState } from 'react'
import type { KeyboardEvent, RefObject } from 'react'

import { Checkbox } from '@/components/ui/Checkbox'
import { cn } from '@/lib/cn'
import { normalizeText } from '@/lib/text'

import { TODO_TASK_TEXT_REFUSALS, todoTaskTextVerdict } from '../lib/todoTask'
import type { RefusedText, TodoTask } from '../lib/todoTask'
import { DeleteTodoTaskDialog } from './DeleteTodoTaskDialog'

/**
 * One task: its box, its text drawn done or not done, its correction in place,
 * and the one question before it is deleted (`spec/design/ui/todo-list.md` § A
 * task's row).
 *
 * **Done shows three ways at once** -- the box filled and ticked, the text struck
 * through in `--color-muted`, and the checked state assistive technology reads --
 * so colour is never the only carrier (`BR-09`). The done text is never greyed with
 * `--color-disabled` or with opacity: it measures 7.09:1 on the card and stays
 * exactly as readable as any other text, which is the contrast defect
 * `spec/design/ui/system-states.md` § Tokens records, kept out of this screen.
 *
 * **A tick sends the state the person chose, and the box goes on showing what is
 * stored until the answer.** The box is a controlled input over `task.done`, so a
 * press asks for the other state and changes nothing on screen by itself; while the
 * tick travels the box is locked on the stored state with "Saving…" beside it, and
 * when the list is read again it shows what the service stored (`R-10`).
 *
 * **Which row is being edited is the page's**, because at most one editor is ever
 * open and a row cannot see its neighbours -- the guestbook card's arrangement. The
 * row asks to start and to stop, and draws what it is told.
 *
 * **The delete question is the row's.** It exists only on the screen, it is about
 * this task alone, and nothing is sent until it is answered (`R-7`). The page is
 * told only the answer, and tells the row back while the deletion travels; the
 * question closes once the deletion itself has been answered, either way -- on the
 * promise `onDelete` returns, not on watching `isDeleting` rise and fall, because
 * a deletion answered before the screen drew it travelling never rises at all.
 *
 * **The focus goes back where the person was** (`Q-16`): a locked control lets go
 * of it, so when the answer comes it is put back -- on the box after a tick, in the
 * edit field after a correction that did not go through, on "Edit" when the editor
 * closes, on "Delete" when the question closes -- but only when it was on the
 * control that was locked and nobody has moved it since. A person who put the
 * focus somewhere else meanwhile keeps it where they put it.
 */
export interface TodoTaskRowProps {
  task: TodoTask
  /** True when this row's editor is the one open on the screen. */
  isEditing: boolean
  onEditStart: () => void
  onEditCancel: () => void
  /** A correction: the new text alone, as the shared rule leaves it. */
  onSave: (values: { text: string }) => void
  /** A tick: the state chosen, alone. */
  onMark: (values: { done: boolean }) => void
  /**
   * The question was answered "Delete task". When it returns a promise, the
   * question closes once that promise settles -- the deletion's answer, whichever
   * way it went; the notice saying so is the caller's.
   */
  onDelete: () => void | Promise<unknown>
  /** True while this task's tick travels. */
  isMarking?: boolean
  /** True while this task's correction travels. */
  isSaving?: boolean
  /**
   * True while **any** task's correction travels, this one's included. "Edit" is
   * locked on every row meanwhile, so the answer can only close the editor that
   * sent it -- the guestbook card's lock, for the reason its docstring gives.
   */
  isSaveInFlight?: boolean
  /** True while this task's deletion travels. */
  isDeleting?: boolean
  /** The service refused a correction's text: shown under the edit field while it holds that text. */
  saveRefusal?: RefusedText
  /** True for a row that has just arrived by an add: it plays the frame's one entry animation. */
  isArriving?: boolean
}

/** The quiet text buttons on the right: `--color-faint`, 5.40:1 on the card. */
const ACTION =
  'cursor-pointer border-0 bg-transparent p-0 text-meta leading-6 text-faint disabled:cursor-default disabled:opacity-50'

export function TodoTaskRow({
  task,
  isEditing,
  onEditStart,
  onEditCancel,
  onSave,
  onMark,
  onDelete,
  isMarking = false,
  isSaving = false,
  isSaveInFlight = false,
  isDeleting = false,
  saveRefusal,
  isArriving = false,
}: TodoTaskRowProps) {
  const boxId = useId()
  const rowRef = useRef<HTMLLIElement>(null)
  const boxRef = useRef<HTMLInputElement>(null)
  const editRef = useRef<HTMLButtonElement>(null)
  const deleteRef = useRef<HTMLButtonElement>(null)

  const [asking, setAsking] = useState(false)

  function confirmDelete() {
    const answered = onDelete()
    // Closed from the same chain of promises the caller's notice is pushed in, so
    // both land in one commit: a notice inserted while the question still made the
    // page behind it inert is a notice nobody hears (`Modal.tsx`, the reason its
    // own effect is a layout one).
    const close = () => setAsking(false)
    if (answered !== undefined) void answered.then(close, close)
  }

  /** Whether the tick in flight was sent from the box while it had the focus. */
  const boxHadFocus = useRef(false)
  const focusIsFree = () => focusIsFreeWithin(rowRef)

  useWhenSettled(isMarking, () => {
    if (boxHadFocus.current && focusIsFree()) boxRef.current?.focus()
    boxHadFocus.current = false
  })
  useWhenSettled(isEditing, () => {
    // The editor closed on "Save" or "Cancel". Closed because another row's
    // "Edit" was pressed, the focus is already in that row's editor.
    if (focusIsFree()) editRef.current?.focus()
  })
  /**
   * The Modal hands the focus back to "Delete" itself, except when "Delete" is
   * still locked at that moment -- the question can close before the page has
   * drawn the deletion as over -- so it is handed over here once the button can
   * take it, unless the person has put the focus somewhere else meanwhile.
   */
  const focusBackToDelete = useRef(false)
  useWhenSettled(asking, () => {
    focusBackToDelete.current = true
  })
  useEffect(() => {
    if (!focusBackToDelete.current || isDeleting) return
    focusBackToDelete.current = false
    if (focusIsFree()) deleteRef.current?.focus()
  })

  const editWord = isEditing ? 'Editing' : 'Edit'
  const deleteWord = isDeleting ? 'Deleting…' : 'Delete'

  return (
    <li
      ref={rowRef}
      className={cn('flex items-start gap-4 px-5 py-3.5', isArriving && 'motion-safe:animate-rise')}
    >
      <div className="flex min-w-0 flex-1 items-start gap-3">
        <Checkbox
          ref={boxRef}
          id={boxId}
          checked={task.done}
          disabled={isMarking}
          // While the row is editing, the text that labels the box is replaced by
          // the edit field, so the stored text names the box instead.
          aria-label={isEditing ? task.text : undefined}
          onChange={(event) => {
            boxHadFocus.current = document.activeElement === event.currentTarget
            onMark({ done: event.currentTarget.checked })
          }}
        />
        {isEditing ? (
          <TodoTaskEditor
            // Remounted per task, so an editor always starts from what that task
            // holds now rather than from the last one's text.
            key={task.id}
            task={task}
            isSaving={isSaving}
            refusal={saveRefusal}
            onSave={onSave}
            onCancel={onEditCancel}
          />
        ) : (
          <label
            htmlFor={boxId}
            className={cn(
              'min-w-0 cursor-pointer text-base leading-6 wrap-anywhere',
              task.done ? 'text-muted line-through' : 'text-ink',
            )}
          >
            {task.text}
          </label>
        )}
      </div>

      {isMarking && <span className="shrink-0 text-meta leading-6 text-faint">Saving…</span>}

      <span className="flex shrink-0 gap-3.5">
        <button
          ref={editRef}
          type="button"
          onClick={onEditStart}
          disabled={isEditing || isSaveInFlight || isDeleting}
          aria-label={`${editWord} “${task.text}”`}
          className={cn(ACTION, 'enabled:hover:text-accent')}
        >
          {editWord}
        </button>
        <button
          ref={deleteRef}
          type="button"
          onClick={() => setAsking(true)}
          disabled={isDeleting}
          aria-label={`${deleteWord} “${task.text}”`}
          className={cn(ACTION, 'enabled:hover:text-danger')}
        >
          {deleteWord}
        </button>
      </span>

      {asking && (
        <DeleteTodoTaskDialog
          task={task}
          isPending={isDeleting}
          onConfirm={confirmDelete}
          onCancel={() => setAsking(false)}
        />
      )}
    </li>
  )
}

interface TodoTaskEditorProps {
  task: TodoTask
  isSaving: boolean
  refusal: RefusedText | undefined
  onSave: (values: { text: string }) => void
  onCancel: () => void
}

/**
 * The edit field, open in the row over the text it replaces, with "Save" and
 * "Cancel" under it.
 *
 * Not exported: an editor with no task under it is not a thing this screen has.
 *
 * The same rule as the add field, from the same module, so a correction cannot do
 * what a new task is forbidden from doing (`R-6` clause 4). The rule's sentence
 * appears once the field is left or Enter is pressed, never while typing, and goes
 * as soon as the text passes. **Escape does nothing here**: a stray key must not
 * lose an edit.
 */
function TodoTaskEditor({ task, isSaving, refusal, onSave, onCancel }: TodoTaskEditorProps) {
  const errorId = useId()
  const containerRef = useRef<HTMLDivElement>(null)
  const fieldRef = useRef<HTMLInputElement>(null)
  const [text, setText] = useState(task.text)
  const [shown, setShown] = useState(false)

  const verdict = todoTaskTextVerdict(text)
  const sent = normalizeText(text)
  const sentence =
    shown && verdict !== 'accepted'
      ? TODO_TASK_TEXT_REFUSALS[verdict]
      : refusal !== undefined && refusal.text === sent
        ? refusal.sentence
        : undefined
  const canSave = verdict === 'accepted' && !isSaving

  /** Whether the correction in flight was sent while the focus was in this editor. */
  const hadFocus = useRef(false)
  useWhenSettled(isSaving, () => {
    // Still open, so the correction did not go through: back in the field, with
    // what was typed, to be sent again or cancelled.
    if (hadFocus.current && focusIsFreeWithin(containerRef)) fieldRef.current?.focus()
    hadFocus.current = false
  })

  function save() {
    if (isSaving) return
    if (verdict !== 'accepted') {
      setShown(true)
      return
    }
    hadFocus.current = containerRef.current?.contains(document.activeElement) ?? false
    onSave({ text: sent })
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter' || event.nativeEvent.isComposing) return
    event.preventDefault()
    save()
  }

  return (
    <div ref={containerRef} className="flex min-w-0 flex-1 flex-col gap-3">
      <div className="flex flex-col gap-1.5">
        <input
          ref={fieldRef}
          type="text"
          aria-label="Edit task"
          autoComplete="off"
          // The editor opens because the person asked for it, and the focus goes
          // where the words are.
          autoFocus
          value={text}
          disabled={isSaving}
          aria-invalid={sentence !== undefined}
          aria-describedby={sentence !== undefined ? errorId : undefined}
          onChange={(event) => {
            const next = event.target.value
            setText(next)
            if (todoTaskTextVerdict(next) === 'accepted') setShown(false)
          }}
          onBlur={() => setShown(verdict !== 'accepted')}
          onKeyDown={handleKeyDown}
          className="w-full rounded-control-tight border border-hairline bg-card px-3 py-2 text-base leading-6 text-ink disabled:bg-surface"
        />
        {sentence !== undefined && (
          <span id={errorId} role="alert" className="text-xs font-medium text-danger">
            {sentence}
          </span>
        )}
      </div>
      <div className="flex gap-2">
        <button
          type="button"
          onClick={save}
          disabled={!canSave}
          className="cursor-pointer rounded-control-tight border-0 bg-accent px-4 py-2 text-meta font-medium text-inverse enabled:hover:brightness-112 disabled:cursor-not-allowed disabled:opacity-35"
        >
          {isSaving ? 'Saving…' : 'Save'}
        </button>
        <button
          type="button"
          onClick={onCancel}
          disabled={isSaving}
          className="cursor-pointer rounded-control-tight border border-hairline bg-transparent px-4 py-2 text-meta text-muted enabled:hover:bg-surface-medium disabled:cursor-default disabled:opacity-50"
        >
          Cancel
        </button>
      </div>
    </div>
  )
}

/**
 * Runs `settle` after the commit in which `flag` falls from true to false -- when
 * the answer to a write has come and the control it locked is usable again.
 */
function useWhenSettled(flag: boolean, settle: () => void): void {
  const previous = useRef(flag)
  useEffect(() => {
    if (previous.current && !flag) settle()
    previous.current = flag
  })
}

/**
 * Whether the focus may be put back: it was dropped (it rests on the page itself,
 * which is where a locked or removed control leaves it) or it is still inside the
 * part of the screen that was locked. Anywhere else, the person put it there.
 */
function focusIsFreeWithin(region: RefObject<HTMLElement | null>): boolean {
  const active = document.activeElement
  if (active === null || active === document.body) return true
  return region.current?.contains(active) ?? false
}

import { useEffect, useRef } from 'react'

import { Button } from '@/components/ui/Button'
import { Modal } from '@/components/ui/Modal'

import type { TodoTask } from '../lib/todoTask'

/**
 * The one question before a task is deleted (`R-7`,
 * `spec/design/ui/todo-list.md` § The delete question).
 *
 * Deleting is permanent -- a deleted task is gone, with no undo anywhere
 * (`BR-13`) -- anybody may delete any task, and "Delete" sits a few pixels from
 * "Edit". So nothing is sent until the person has answered, and the question
 * **quotes the task it is about**: rows differ only by their text, so a question
 * that does not name what it will destroy cannot be answered correctly.
 *
 * The focus starts on "Cancel", so an Enter pressed out of habit deletes nothing,
 * and Tab stays inside the question -- the guestbook's delete dialog and its focus
 * rules, as they are, over the same `Modal` primitive.
 *
 * **While the deletion travels the question cannot be closed**: both buttons are
 * locked, "Deleting…" says why, and Escape and a press on the backdrop do nothing
 * -- there is nothing left to cancel, and closing would only hide what is still
 * happening. The focus rests on the question itself meanwhile, because a locked
 * button lets go of it and it must not fall behind the question onto a page the
 * question is covering.
 */
export interface DeleteTodoTaskDialogProps {
  task: TodoTask
  onConfirm: () => void
  onCancel: () => void
  /** True while this task's deletion travels. */
  isPending?: boolean
}

export function DeleteTodoTaskDialog({
  task,
  onConfirm,
  onCancel,
  isPending = false,
}: DeleteTodoTaskDialogProps) {
  const cancelRef = useRef<HTMLButtonElement>(null)
  const quoteRef = useRef<HTMLParagraphElement>(null)

  useEffect(() => {
    if (!isPending) return
    // The dialog container is the Modal's own, focusable by design (it catches
    // the focus a locked control drops); reached from inside rather than through
    // a new prop on a primitive that has one other caller.
    quoteRef.current?.closest<HTMLElement>('[role="dialog"]')?.focus()
  }, [isPending])

  return (
    <Modal
      title="Delete this task?"
      onDismiss={isPending ? undefined : onCancel}
      initialFocusRef={cancelRef}
      footer={
        <>
          <span className="text-xs text-muted">This cannot be undone.</span>
          <div className="ml-auto flex gap-2">
            <Button ref={cancelRef} variant="quiet" onClick={onCancel} disabled={isPending}>
              Cancel
            </Button>
            <Button variant="primary" onClick={onConfirm} disabled={isPending}>
              {isPending ? 'Deleting…' : 'Delete task'}
            </Button>
          </div>
        </>
      }
    >
      {/* The text as stored, in the quotation block; an unbroken run breaks
          anywhere rather than widening the question. */}
      <p ref={quoteRef} className="m-0 rounded-xl bg-surface px-3 py-2.5 text-sm wrap-anywhere">
        {task.text}
      </p>
    </Modal>
  )
}

